// EComm — standalone scene 4 (Scene4Pipeline). Transparent background, no scene-level
// fade in/out. Content animates in via its own springs; <Background/> + SceneWrap removed.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "monospace";

const LogoTile: React.FC<{
  progress: number;
  children: React.ReactNode;
  size: number;
}> = ({ progress, children, size }) => {
  const tx = interpolate(progress, [0, 1], [30, 0]);
  const sc = interpolate(progress, [0, 1], [0.85, 1]);
  return (
    <div
      style={{
        width: size,
        height: size,
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: size * 0.12,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: size * 0.18,
        opacity: progress,
        transform: `translateY(${tx}px) scale(${sc})`,
        boxShadow: "0 18px 40px rgba(0,0,0,0.4)",
      }}
    >
      {children}
    </div>
  );
};

const Scene4Pipeline: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Logos appear sequentially (Apify, Zapier, Power BI)
  const apifyIn = springIn(frame, vfps, 6, "ELASTIC");
  const zapierIn = springIn(frame, vfps, 26, "ELASTIC");
  const pbiIn = springIn(frame, vfps, 46, "ELASTIC");

  // The connecting line draws after the logos; the clock resolves at the end.
  const lineDraw = springIn(frame, vfps, 64, "LIQUID");
  const clockIn = springIn(frame, vfps, 88, "LIQUID");
  // Minute hand sweeps exactly a quarter — 12 -> 3 o'clock (the 15-minute mark)
  // — and holds there, so the clock reads as "15 minutes".
  const sweep = interpolate(frame, [95, 185], [0, 90], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Orange wedge filling the first quarter in sync with the hand.
  const wedgeR = 40;
  const wedgeRad = (sweep * Math.PI) / 180;
  const wedgeEx = (50 + wedgeR * Math.sin(wedgeRad)).toFixed(2);
  const wedgeEy = (50 - wedgeR * Math.cos(wedgeRad)).toFixed(2);
  const wedgePath = `M 50 50 L 50 ${50 - wedgeR} A ${wedgeR} ${wedgeR} 0 0 1 ${wedgeEx} ${wedgeEy} Z`;

  // Flow pulse travelling along the line (logos -> clock), looping.
  // Single flow pulse: travels logos -> clock exactly once, then it's gone.
  const pulseProgress = interpolate(frame, [72, 95], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pulseVisible = frame >= 72 && frame < 96;

  const logoSize = base * 0.15;
  const clockSize = base * 0.2;

  const driftY = ambientDrift(frame, 2, 120, "pipe");

  const logoImg = (src: string) => (
    <Img
      src={staticFile(src)}
      style={{ width: "100%", height: "100%", objectFit: "contain" }}
    />
  );

  return (
    <AbsoluteFill>
      {null}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          padding: `${base * 0.08}px ${base * 0.09}px`,
          transform: `translateY(${driftY}px)`,
        }}
      >
        {/* Logos group (left) */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: base * 0.022,
            flexShrink: 0,
          }}
        >
          <LogoTile progress={apifyIn} size={logoSize}>
            {logoImg("assets/apify/Apify symbol colors.svg")}
          </LogoTile>
          <LogoTile progress={zapierIn} size={logoSize}>
            {logoImg("assets/logos/Zapier.png")}
          </LogoTile>
          <LogoTile progress={pbiIn} size={logoSize}>
            {logoImg("assets/logos/PowerBI.png")}
          </LogoTile>
        </div>

        {/* Connecting line: logos -> clock */}
        <div
          style={{
            position: "relative",
            flex: 1,
            height: base * 0.03,
            margin: `0 ${base * 0.025}px`,
            display: "flex",
            alignItems: "center",
          }}
        >
          {/* the line, draws left -> right */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: "50%",
              height: base * 0.004,
              width: `${lineDraw * 100}%`,
              background: COLORS.orange,
              borderRadius: base * 0.002,
              transform: "translateY(-50%)",
            }}
          />
          {/* single flow pulse */}
          {pulseVisible && (
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: `${pulseProgress * 100}%`,
                width: base * 0.014,
                height: base * 0.014,
                borderRadius: "50%",
                background: COLORS.orange,
                boxShadow: `0 0 ${base * 0.018}px ${COLORS.orange}`,
                transform: "translate(-50%, -50%)",
              }}
            />
          )}
        </div>

        {/* Clock (right) */}
        <div
          style={{
            flexShrink: 0,
            opacity: clockIn,
            transform: `scale(${interpolate(clockIn, [0, 1], [0.5, 1])})`,
          }}
        >
          <div
            style={{
              position: "relative",
              width: clockSize,
              height: clockSize,
            }}
          >
            <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%" }}>
              {/* Outer ring */}
              <circle
                cx="50"
                cy="50"
                r="44"
                fill={COLORS.card}
                stroke={COLORS.orange}
                strokeWidth={2}
              />
              {/* Tick marks */}
              {Array.from({ length: 12 }).map((_, i) => {
                const angle = (i * 30 * Math.PI) / 180;
                const x1 = 50 + Math.sin(angle) * 38;
                const y1 = 50 - Math.cos(angle) * 38;
                const x2 = 50 + Math.sin(angle) * 42;
                const y2 = 50 - Math.cos(angle) * 42;
                return (
                  <line
                    key={i}
                    x1={x1}
                    y1={y1}
                    x2={x2}
                    y2={y2}
                    stroke={COLORS.orange}
                    strokeWidth={i % 3 === 0 ? 2 : 1}
                    opacity={1}
                  />
                );
              })}
              {/* 15-minute wedge — solid orange quarter, fills as the hand sweeps */}
              {sweep > 0.5 && (
                <path d={wedgePath} fill={COLORS.orange} />
              )}
              {/* Hour hand (short, points to 12) */}
              <line
                x1="50"
                y1="50"
                x2="50"
                y2="28"
                stroke={COLORS.text}
                strokeWidth={3}
                strokeLinecap="round"
              />
              {/* Minute hand — sweeps to the 15-minute mark (3 o'clock).
                  White so it stays visible on the solid orange wedge. */}
              <line
                x1="50"
                y1="50"
                x2="50"
                y2="14"
                stroke={COLORS.text}
                strokeWidth={3}
                strokeLinecap="round"
                transform={`rotate(${sweep}, 50, 50)`}
              />
              {/* Center dot */}
              <circle cx="50" cy="50" r="3.5" fill={COLORS.text} />
            </svg>

            {/* 15-minute label under the dial */}
            <div
              style={{
                position: "absolute",
                top: "104%",
                left: "50%",
                transform: "translateX(-50%)",
                whiteSpace: "nowrap",
                fontFamily: FONT_MARKETING,
                fontWeight: 700,
                fontSize: base * 0.036,
                letterSpacing: "-0.01em",
                color: COLORS.text,
              }}
            >
              ~15 min
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// =====================================================
